---- LOOK AND FEEL ----

-- Active-window border color follows the wallpaper palette (generated by theme.py).
local okc, palette = pcall(require, "colors")
if not okc then palette = { active = "rgba(c2c6d6ff)", inactive = "rgba(c2c6d600)" } end

-- Window settings saved from Settings > Windows (hypr/prefs.lua, written by scripts/apply-window-prefs.sh).
local okp, prefs = pcall(require, "prefs")
if not okp then prefs = {} end

hl.config({ render = { expand_undersized_textures = false}})
hl.config({
    general = {
        gaps_in = prefs.gaps_in or 4,
        gaps_out = {
            top = 5,
            right = 8,
            bottom = 8,
            left = 8,
        },
        border_size = prefs.border_size or 2,
        col = { active_border = palette.active, inactive_border = palette.inactive },
        resize_on_border = true,
        allow_tearing = false,
        layout = "dwindle",
    },
    decoration = {
        rounding = prefs.rounding or 8,
        blur = {
            enabled = true,
            size = 5,
            passes = 1,
            vibrancy = 0.2,
        },
        shadow = {
            enabled = true,
            range = 4,
            render_power = 3,
        },
    },
    animations = {
        enabled = false,   -- off, as it has been since HyprMod set it; the curves below apply if you turn this on
    },
})

hl.curve("easeOut", { type = "bezier", points = { {0.05, 0.9}, {0.1, 1.0} } })

hl.animation({ leaf = "windows",    enabled = true, speed = 5, bezier = "easeOut" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 5, bezier = "easeOut" })
hl.animation({ leaf = "border",     enabled = true, speed = 5, bezier = "default" })
hl.animation({ leaf = "fade",       enabled = true, speed = 4, bezier = "default" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 6, bezier = "default", style = "slidefadevert" }) -- styles: "slide", "slidefade", "slidevert", "slidefadevert"

